<header class="page-header"><div><h1><?= e(t('Time planning')) ?></h1><p><?= e(t('Schedule tasks into free time. Appointments, existing blocks and deadlines are protected.')) ?></p></div><a href="/planner"><?= e(t('Planner')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card"><h2><?= e(t('Availability')) ?></h2><form class="stack" method="post" action="/planner/planning/preferences"><?= csrf_field() ?><label><?= e(t('Start')) ?><input name="start" type="time" value="<?= e($preferences['start']) ?>" required></label><label><?= e(t('End')) ?><input name="end" type="time" value="<?= e($preferences['end']) ?>" required></label><fieldset><legend><?= e(t('Weekdays')) ?></legend><?php foreach (PlannerService::DAYS as $n=>$label): ?><label><input type="checkbox" name="days[]" value="<?= $n ?>" <?= in_array((string)$n,$preferences['days'],true)?'checked':'' ?>><?= e($label) ?></label><?php endforeach; ?></fieldset><label><input type="checkbox" name="enabled" <?= $preferences['enabled']?'checked':'' ?>><?= e(t('Automatic daily time-blocking')) ?></label><label><input type="checkbox" name="reschedule" <?= $preferences['reschedule']?'checked':'' ?>><?= e(t('Auto-reschedule overdue tasks (search next 14 days)')) ?></label><label><?= e(t('Archive completed tasks after N days (0 disables)')) ?><input type="number" name="archive_days" min="0" max="3650" value="<?= e($preferences['archive_days']) ?>" required></label><p class="muted"><?= e(t('Runs once per day while the resident app runs, after availability starts. Undo plans below. Archived tasks retain their completion history.')) ?></p><button><?= e(t('Save')) ?></button></form></section>
<section class="card"><h2><?= e(t('Preview plan')) ?></h2><form class="stack" action="/planner/planning/preview" method="post"><?= csrf_field() ?><label><?= e(t('Date')) ?><input type="date" name="date" value="<?= e($preview['date'] ?? ui_date('Y-m-d')) ?>" min="<?= e(ui_date('Y-m-d')) ?>" required></label><label><input type="checkbox" name="reschedule"><?= e(t('Move overdue due dates to their new block dates')) ?></label><button><?= e(t('Preview')) ?></button></form>
<?php if ($preview): ?><h3><?= e($preview['date']) ?></h3><?php foreach ($preview['changes'] as $c): ?><p><strong><?= e($c['title']) ?></strong><br><?= e($c['starts_at']) ?> → <?= e($c['ends_at']) ?><br><?= e(t('Due:')) ?> <?= e($c['before_due'] ?? t('Undated')) ?> → <?= e($c['after_due'] ?? t('Undated')) ?></p><?php endforeach; ?><?php foreach ($preview['unscheduled'] as $c): ?><p class="error-text"><?= e($c['title'].': '.$c['reason']) ?></p><?php endforeach; ?><?php if ($preview['changes']): ?><form action="/planner/planning/apply" method="post"><?= csrf_field() ?><button><?= e(t('Apply this plan')) ?></button></form><?php endif; ?><?php endif; ?></section></div>
<section class="card"><h2><?= e(t('Scheduled blocks')) ?></h2><?php if (!$blocks): ?><p class="muted"><?= e(t('No blocks scheduled yet. Preview a plan to get started.')) ?></p><?php endif; ?><?php foreach ($blocks as $block): ?><div class="task-row"><div><strong><?= e($block['title']) ?></strong><small><?= e($block['starts_at'].' → '.$block['ends_at']) ?><?= $block['pinned']?' · Pinned':'' ?></small></div><form method="post" action="/planner/blocks/<?= e($block['id']) ?>/pin"><?= csrf_field() ?><button class="secondary"><?= $block['pinned']?t('Unpin'):t('Pin') ?></button></form><form method="post" action="/planner/blocks/<?= e($block['id']) ?>/delete"><?= csrf_field() ?><button class="quiet" <?= $block['pinned'] ? 'disabled title="Unpin this block before removing it"' : '' ?>><?= e(t('Remove block')) ?></button></form></div><?php endforeach; ?></section>
<section class="card"><h2><?= e(t('Plan history')) ?></h2><?php if (!$batches): ?><p class="muted"><?= e(t('Applied plans and undo actions will appear here.')) ?></p><?php endif; ?><?php foreach ($batches as $batch): ?><div class="task-row"><span><?= e($batch['created_at'].' · '.$batch['kind']) ?></span><?php if (!$batch['undone']): ?><form action="/planner/planning/<?= e($batch['id']) ?>/undo" method="post"><?= csrf_field() ?><button class="secondary"><?= e(t('Undo')) ?></button></form><?php else: ?><?= e(t('Undone')) ?><?php endif; ?></div><?php endforeach; ?></section>
